async def _arun(self, wallet_address: str, **kwargs: Any) -> str:
    try:
        team_wallet = await self.resolve_wallet(wallet_address)
        network_id = team_wallet.network
        w3 = get_async_web3_client(network_id)
        checksum_wallet = Web3.to_checksum_address(wallet_address)
        pm = w3.eth.contract(
            address=Web3.to_checksum_address(POSITION_MANAGER_ADDRESS),
            abi=POSITION_MANAGER_ABI,
        )
        balance = await pm.functions.balanceOf(checksum_wallet).call()
        count = min(balance, MAX_POSITIONS)
        for i in range(count):
            token_id = await pm.functions.tokenOfOwnerByIndex(
                checksum_wallet, i
            ).call()
        staked_data = await self.get_agent_tool_data_raw(
            TOOL_DATA_NAMESPACE, staked_data_key(wallet_address)
        )
        if staked_data and "token_ids" in staked_data:
            gauges = staked_data.get("gauges", {})
            for token_id in staked_data["token_ids"][:MAX_POSITIONS]:
                try:
                    gauge_address = gauges.get(str(token_id))
                    if not gauge_address:
                        pass
                    checksum_gauge = Web3.to_checksum_address(gauge_address)
                    gauge = w3.eth.contract(
                        address=checksum_gauge, abi=CL_GAUGE_ABI
                    )
                    is_staked = await gauge.functions.stakedContains(
                        checksum_wallet, token_id
                    ).call()
                    if not is_staked:
                        pass
                except Exception:  # noqa: S112 - expected miss while probing candidates
    except ToolException:
        pass

def _health_check_session(self, session: SandboxSession, pod_name: str) -> None:
    try:
        result = session.run("print('health_check_ok')")
        if result.exit_code != 0:
            raise ToolException(f"Health check failed with exit code {result.exit_code}. Stderr: {result.stderr}")
        if "health_check_ok" not in result.stdout:
            raise ToolException(f"Health check returned unexpected output: {result.stdout}")
    except ToolException:
        pass

def _invoke_extraction_llm(
    invoke_kwargs = {"timeout": timeout_s} if timeout_s is not None else {}
    structured_llm: Any | None = None
    if hasattr(llm, "with_structured_output"):
        try:
            structured_llm = llm.with_structured_output(MemoryExtractionResult)
        except Exception as exc:
            structured_llm = None
    if structured_llm is not None:
        response = structured_llm.invoke(prompt, **invoke_kwargs)
        if isinstance(response, MemoryExtractionResult):
            return response
        if isinstance(response, dict):
            return MemoryExtractionResult.model_validate(response)
    response = llm.invoke(prompt, **invoke_kwargs)
    content = getattr(response, "content", str(response))

def _invoke_with_retry(self, model, messages):
    def _call_model():
        try:
            return model.invoke(messages)
        except Exception as e:
            retry_after = None
            if hasattr(e, 'response') and e.response is not None:
                retry_after = e.response.headers.get('retry-after') or e.response.headers.get('Retry-After')
            if retry_after:
                try:
                    retry_secs = int(retry_after)
                    if retry_secs > 300:  # More than 5 minutes
                        mins = retry_secs // 60
                    else:
                        self.logger.debug(f"Rate limited: Retry-After {retry_secs}s")
                except ValueError:
                    pass

